"гибнут рыбы и растения": "балықтар мен өсімдіктер қырылады",
"делает воду вкуснее": "суды дәмдірек етеді",
"Живые организмы страдают": "Тірі организмдер зардап шегеді",
"Как беречь воду?": "Суды қалай сақтайды?",
"не мусорить у водоёмов": "су айдындарының маңында қоқыстамау",
"выбрасывать мусор": "қоқысты лақтыру",
"сливать масло": "майды төгу",
"мыть машину в реке": "көлікті өзенде жуу",
"Берегите чистоту воды": "Судың тазалығын сақтаңдар",
"Что такое круговорот воды?": "Судың айналымы дегеніміз не?",
