"Пыльцу могут переносить насекомые, ветер и вода.": "Тозаңды жәндіктер, жел және су тасымалдай алады.",
"Развитие насекомого начинается с яйца.": "Жәндіктің дамуы жұмыртқадан басталады.",
"Развитие насекомого начинается с яйца. Бабочка прячет яйца на обратной стороне листа.": "Жәндіктің дамуы жұмыртқадан басталады. Көбелек жұмыртқаларын жапырақтың астыңғы жағына жасырады.",
"Различать низшие и высшие растения и объяснять роль растений в пищевой цепи": "Төменгі және жоғарғы өсімдіктерді ажырату және өсімдіктердің қоректік тізбектегі рөлін түсіндіру",
"Различать травоядных и хищных животных и приводить примеры симбиоза": "Шөпқоректі және жыртқыш жануарларды ажырату және симбиозға мысал келтіру",
"Различаются в основном размерами": "Негізінен мөлшерімен ерекшеленеді",
