"Урок 3. Как распространяются семена — Білім Аралы": "Сабақ 3. Тұқымдар қалай таралады — Білім Аралы",
"Урок 3: Урок 3. Как распространяются семена": "Сабақ 3: Сабақ 3. Тұқымдар қалай таралады",
