"Это превращение пара в капли": "Бұл — будың тамшыға айналуы",
"Это природный помощник очистки": "Бұл — тазартудың табиғи көмекшісі",
"Это происходит без участия человека": "Бұл адамның қатысынсыз өтеді",
"Это снежинки": "Бұл — қар ұлпалары",
"Это углекислый газ": "Бұл — көмірқышқыл газы",
"Это часть пищеварительной системы": "Бұл — ас қорыту жүйесінің бөлігі",
"Это эксперимент с условиями и сравнением": "Бұл — жағдайлары мен салыстыруы бар тәжірибе",
"Это явление природы, а не дело человека": "Бұл — табиғат құбылысы, адамның ісі емес",
