"Астероиды": "Астероидтар",
"Астероиды — каменные или металлические тела, которые обращаются вокруг Солнца. Больше всего их в поясе между Марсом и Юпитером. Астероид Веста иногда виден даже без телескопа в тёмном небе: она сама не светится, а отражает свет Солнца.": "Астероидтар — Күнді айналып жүретін тастан немесе металдан тұратын денелер. Олар көбіне Марс пен Юпитер аралығындағы белдеуде орналасқан. Веста астероидын кейде қараңғы аспанда телескопсыз да көруге болады: ол өзі жарқырамайды, Күннің жарығын шағылыстырады.",
"Астероиды — каменные или металлические тела.": "Астероидтар — тастан немесе металдан тұратын денелер.",
"Атлантический": "Атлант",
"Атлантический океан": "Атлант мұхиты",
"Африка — самый маленький материк.": "Африка — ең кішкентай материк.",
"Барсик бросает предметы в воду. Нажимай на карточки и узнавай, что происходит.": "Барсик заттарды суға тастайды. Карточкаларды басып, не болатынын біл.",
"Барсик предлагает повторить главное за год. Нажимай на карточки.": "Барсик жыл бойы өткен ең маңызды нәрсені қайталауды ұсынады. Карточкаларды бас.",
"Барсик приглашает в космос. Нажимай на карточки.": "Барсик ғарышқа шақырады. Карточкаларды бас.",
"Барсик приглашает на прогулку по глобусу. Нажимай на карточки.": "Барсик глобус бойымен серуендеуге шақырады. Карточкаларды бас.",
"Без наклона земной оси сезоны менялись бы сильнее, чем сейчас.": "Жер осінің еңкеюі болмаса, жыл мезгілдері қазіргіден әлдеқайда қатты өзгерер еді.",
"Без наклона сезонов почти не было бы": "Еңкею болмаса, жыл мезгілдері дерлік болмас еді",
"Без него не было бы жизни": "Онсыз тіршілік болмас еді",
"Ближе всего Земля в начале января, а сезоны зависят от наклона": "Жер қаңтардың басында Күнге ең жақын болады, ал жыл мезгілдері еңкеюге байланысты",
"Бывает у полюса летом": "Полюсте жазда болады",
"В Австралии в декабре лето.": "Австралияда желтоқсанда жаз.",
"В Южном полушарии в это время зима": "Оңтүстік жарты шарда бұл кезде қыс",
"В Южном полушарии летом дни длинные, а к осени укорачиваются": "Оңтүстік жарты шарда жазда күндер ұзақ, ал күзге қарай қысқарады",
"В Южном полушарии сезоны противоположны": "Оңтүстік жарты шарда жыл мезгілдері қарама-қарсы",
"В високосном году 366 дней.": "Кібісе жылы 366 күн болады.",
"В воде большой камень поднять легче, чем в воздухе.": "Суда үлкен тасты көтеру ауадағыға қарағанда оңай.",
"В воде на любое тело действует выталкивающая сила, или сила Архимеда. Она направлена вверх, а сила тяжести тянет тело вниз. Чем больше воды вытесняет тело, тем больше выталкивающая сила.": "Суда кез келген денеге итеруші күш, яғни Архимед күші әсер етеді. Ол жоғары бағытталған, ал ауырлық күші денені төмен тартады. Дене неғұрлым көп суды ығыстырса, итеруші күш соғұрлым үлкен болады.",
"В воде на тело действуют две силы: сила тяжести тянет вниз, а сила Архимеда выталкивает вверх.": "Суда денеге екі күш әсер етеді: ауырлық күші төмен тартады, ал Архимед күші жоғары итереді.",
"В воде на тело перестаёт действовать сила тяжести.": "Суда денеге ауырлық күші әсер етпейді.",
"В декабре там лето": "Желтоқсанда онда жаз",
"В дни равноденствия день равен ночи.": "Күн мен түннің теңелу күндері күн мен түн тең болады.",
"В какой из этих стран Новый год встречают летом?": "Осы елдердің қайсысында Жаңа жылды жазда қарсы алады?",
"В народе его зовут «падающей звездой»": "Оны халық «аққан жұлдыз» дейді",
