"Важен общий объём корабля": "Кеменің жалпы көлемі маңызды",
"Важны наклон оси и годовой путь вокруг Солнца": "Осьтің еңкеюі мен Күнді айнала жылдық жолы маңызды",
"Верно. В феврале 29 дней": "Дұрыс. Ақпанда 29 күн болады",
"Верно. Ветер приносит и пользу, и вред.": "Дұрыс. Жел пайда да, зиян да әкеледі.",
