"Верно. Граница проходит условно": "Дұрыс. Шекара шартты түрде жүргізіледі",
"Верно. Его средняя плотность меньше плотности воды": "Дұрыс. Оның орташа тығыздығы судың тығыздығынан аз",
"Верно. Её передают как предание": "Дұрыс. Оны аңыз ретінде жеткізеді",
