"Верно. Жидкость выталкивает тело": "Дұрыс. Сұйықтық денені жоғары итереді",
"Верно. Звук возвращается к нам, как свет от зеркала.": "Дұрыс. Дыбыс бізге айнадан жарық қайтқандай қайтады.",
"Верно. Земля возвращается в ту же точку за год": "Дұрыс. Жер бір жылда сол нүктеге қайта оралады",
"Верно. Земля по форме близка к шару": "Дұрыс. Жердің пішіні шарға жақын",
"Верно. Из-за наклона лучи падают на полушария по-разному": "Дұрыс. Еңкеюге байланысты сәулелер жарты шарларға әртүрлі түседі",
"Верно. Их используют как топливо.": "Дұрыс. Оларды отын ретінде пайдаланады.",
"Верно. К осадкам относятся и дождь, и снег, и град.": "Дұрыс. Жауын-шашынға жаңбыр да, қар да, бұршақ та жатады.",
"Верно. Колючие плоды цепляются за шерсть.": "Дұрыс. Тікенекті жемістер жүнге жабысады.",
"Верно. Летом Солнце поднимается выше и дольше находится над горизонтом": "Дұрыс. Жазда Күн жоғары көтеріліп, көкжиектен жоғары ұзағырақ тұрады",
"Верно. Луну нельзя изменить, её можно только наблюдать": "Дұрыс. Айды өзгертуге болмайды, оны тек бақылауға болады",
"Верно. Лучи там падают косо": "Дұрыс. Онда сәулелер еңіс түседі",
"Верно. Лёгкое вещество не тонет": "Дұрыс. Жеңіл зат батпайды",
"Верно. Материк лежит в Южном полушарии": "Дұрыс. Материк Оңтүстік жарты шарда орналасқан",
"Верно. Меняем одно условие и смотрим результат.": "Дұрыс. Бір жағдайды өзгертіп, нәтижесін қараймыз.",
"Верно. Метеороид, долетевший до поверхности": "Дұрыс. Жер бетіне жеткен метеороид",
"Верно. Много бросков дают надёжный результат": "Дұрыс. Көп рет лақтыру сенімді нәтиже береді",
"Верно. Можно мерить и сравнивать": "Дұрыс. Өлшеуге және салыстыруға болады",
"Верно. Мы видим её как серебристую полосу": "Дұрыс. Біз оны күміс түсті жолақ ретінде көреміз",
"Верно. Мы записываем данные, не вмешиваясь в явление": "Дұрыс. Құбылысқа араласпай, деректерді жазамыз",
"Верно. Мы сами меняем условия и измеряем": "Дұрыс. Жағдайды өзіміз өзгертіп, өлшейміз",
"Верно. Мы сами меняем условия: наклон и положение": "Дұрыс. Еңкею мен жағдайды өзіміз өзгертеміз",
"Верно. Мы сами погружаем шарики и отмечаем уровень": "Дұрыс. Шарларды өзіміз батырып, деңгейін белгілейміз",
"Верно. Наклон — важная причина смены сезонов": "Дұрыс. Еңкею — жыл мезгілдерінің ауысуының маңызды себебі",
"Верно. Например, в масле или молоке": "Дұрыс. Мысалы, майда немесе сүтте",
"Верно. Наша страна расположена на материке Евразия": "Дұрыс. Біздің ел Еуразия материгінде орналасқан",
"Верно. Небесные тела нельзя изменить.": "Дұрыс. Аспан денелерін өзгертуге болмайды.",
"Верно. Один оборот занимает около суток": "Дұрыс. Бір айналым шамамен тәулікке созылады",
"Верно. Около 12 часов каждый": "Дұрыс. Әрқайсысы шамамен 12 сағат",
"Верно. Окружающий воздух выталкивает такой шар вверх": "Дұрыс. Қоршаған ауа мұндай шарды жоғары итереді",
"Верно. Он возник при падении метеорита": "Дұрыс. Ол метеорит құлағанда пайда болған",
"Верно. Он вытесняет много воды": "Дұрыс. Ол көп суды ығыстырады",
"Верно. Он занимает около половины Мирового океана": "Дұрыс. Ол Әлемдік мұхиттың шамамен жартысын алып жатыр",
"Верно. Он не отвечает всем признакам планеты": "Дұрыс. Ол планетаның барлық белгілеріне сай келмейді",
"Верно. Он спит в укрытии до весны": "Дұрыс. Ол көктемге дейін паналайтын жерінде ұйықтайды",
"Верно. Она направлена вверх": "Дұрыс. Ол жоғары бағытталған",
"Верно. Она направлена вверх.": "Дұрыс. Ол жоғары бағытталған.",
"Верно. Она связывает мозг с органами и мышцами.": "Дұрыс. Ол мидың органдармен және бұлшықеттермен байланысын қамтамасыз етеді.",
"Верно. Она становится тяжелее": "Дұрыс. Ол ауырлайды",
"Верно. Они образуются при конденсации пара.": "Дұрыс. Олар будың конденсациялануынан пайда болады.",
"Верно. Они обращаются вокруг Солнца": "Дұрыс. Олар Күнді айналады",
