"Верно. Планеты же светят отражённым светом.": "Дұрыс. Ал планеталар шағылған жарықпен жарқырайды.",
"Верно. Побеждает сила, направленная вниз": "Дұрыс. Төмен бағытталған күш басым болады",
"Верно. Поэтому в нём видно отражение.": "Дұрыс. Сондықтан онда көрініс көрінеді.",
"Верно. Растения сами создают питательные вещества, и ими питаются животные.": "Дұрыс. Өсімдіктер қоректік заттарды өздері түзеді, оларды жануарлар қорек етеді.",
"Верно. Силы уравновешены": "Дұрыс. Күштер теңестірілген",
"Верно. Силы уравновешивают друг друга": "Дұрыс. Күштер бір-бірін теңестіреді",
"Верно. Солёная вода плотнее пресной": "Дұрыс. Тұзды су тұщы судан тығыз",
